let project=E.makeProject(),selected='r5',tab='content',activeProp='points',time=1.4,playing=false,loop=true,autoKey=false;
let events=[],sketch,p5canvas,lastTick=0,lastUI=0,selectedKey=null,history=[],future=[],rendering=false,cancelled=false,toastTimer,resizeObserver;
let persistFailed=false,curveDraft=null,customFonts=[];
function validateValue(prop,value){const s=Object.hasOwn(SCHEMA,prop)?SCHEMA[prop]:null;if(!s)throw Error('未知属性：'+prop);if(s.type==='number'){const n=Number(value);if(!Number.isFinite(n))throw Error(s.label+'必须是有效数字');return E.clamp(n,s.min,s.max);}if(s.type==='boolean'){if(typeof value!=='boolean')throw Error(s.label+'必须是开关值');return value;}if(typeof value!=='string'||value.length>300)throw Error('文字长度应不超过 300 字');if(s.type==='color'&&!/^#[0-9a-f]{6}$/i.test(value))throw Error('颜色格式应为 #RRGGBB');if(s.type==='select'&&prop!=='font'&&!s.options.map(v=>Array.isArray(v)?v[0]:v).includes(value))throw Error('未知选项');return value;}
function validateProject(raw){
 if(!raw||raw.version!==1||!Array.isArray(raw.rankers)||raw.rankers.length<1||raw.rankers.length>30)throw Error('工程版本不兼容，或选手数量超出 1–30 人');
 const p=E.makeProject();p.name=String(raw.name||'未命名工程').slice(0,100);
 for(const [k,min,max]of [['duration',.1,120],['fps',1,60],['width',240,3840],['height',240,3840]]){if(!Number.isFinite(raw[k])||raw[k]<min||raw[k]>max)throw Error('工程尺寸、时长或帧率无效');p[k]=raw[k];}
 if(![24,25,30,50,60].includes(p.fps))throw Error('不支持的工程帧率');
 p.preview=[960,1280,1920].includes(raw.preview)?raw.preview:1280;
 const clean=(obj,base)=>{if(!obj||typeof obj!=='object')throw Error('属性数据不完整');const out={...base};for(const[k,v]of Object.entries(obj)){if(Object.hasOwn(SCHEMA,k))out[k]=validateValue(k,v);}return out;};
 p.scene=clean(raw.scene,E.DEFAULTS);const ids=new Set();
 p.rankers=raw.rankers.map(r=>{if(typeof r.id!=='string'||!/^r[a-zA-Z0-9_-]+$/.test(r.id)||ids.has(r.id))throw Error('选手 ID 无效或重复');ids.add(r.id);return {...clean(r,E.ROW_DEFAULTS),id:r.id};});
 p.tracks={};let total=0;
 for(const[key,keys]of Object.entries(raw.tracks||{})){const[scope,prop,...rest]=key.split('.');if(rest.length||(!ids.has(scope)&&scope!=='scene')||!Object.hasOwn(SCHEMA,prop)||!Array.isArray(keys))throw Error('关键帧轨道无效');
 p.tracks[key]=keys.map(k=>{if(++total>10000)throw Error('关键帧数量超过 10000');if(!Number.isFinite(k.time)||k.time<0||k.time>p.duration)throw Error('关键帧时间超出合成范围');const c=k.curve||[.42,0,.58,1];if(c.length!==4||c.some(x=>!Number.isFinite(x))||c[0]<0||c[0]>1||c[2]<0||c[2]>1||Math.abs(c[1])>4||Math.abs(c[3])>4)throw Error('贝塞尔曲线无效');return {id:uid('k'),time:k.time,value:validateValue(prop,k.value),ease:k.ease==='hold'?'hold':'custom',curve:c};}).sort((a,b)=>a.time-b.time);
 if(p.tracks[key].some((k,i,a)=>i&&Math.abs(k.time-a[i-1].time)<.00001))throw Error('同一属性含重复时间关键帧');}
 return p;
}
function uid(prefix='r'){return prefix+(crypto.randomUUID?.()||Math.random().toString(36).slice(2)).replaceAll('-','');}
try{const saved=localStorage.getItem(STORAGE);if(saved){project=validateProject(JSON.parse(saved));selected=project.rankers[project.rankers.length-1].id;time=Math.min(1.4,project.duration);}}catch(e){setTimeout(()=>toast('未能读取本机工程，已打开示例。'+e.message),1500);}
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),4200);}
function remember(){history.push(JSON.stringify(project));if(history.length>70)history.shift();future=[];}
function saveLocal(){try{localStorage.setItem(STORAGE,JSON.stringify(project));$('saveState').textContent='已自动保存到本机';persistFailed=false;}catch{persistFailed=true;$('saveState').textContent='自动保存失败 · 请保存工程';}}
function commit({rebuild=true}={}){if(rebuild)events=E.compileRanking(project);saveLocal();renderUI();}
function mutate(fn,options){remember();fn();commit(options);}
function scopeObject(){return selected==='scene'?project.scene:project.rankers.find(r=>r.id===selected);}
function trackKey(){return selected+'.'+activeProp;}
function findKey(){if(!selectedKey)return null;return (project.tracks[selectedKey.track]||[]).find(k=>k.id===selectedKey.id);}
function seek(t){time=E.clamp(Math.round(t*project.fps)/project.fps,0,project.duration);playing=false;$('playBtn').textContent='▶';syncTime();syncInputs();}
function select(scope){selected=scope;selectedKey=null;activeProp=scope==='scene'?'rotation':'points';renderUI();}
function selectProp(prop){activeProp=prop;selectedKey=null;document.querySelectorAll('.prop').forEach(el=>el.classList.toggle('focused',el.dataset.prop===prop));renderTimeline();renderKeyPanel();}
function upsert(scope,prop,t,value){const key=scope+'.'+prop;const list=project.tracks[key]||(project.tracks[key]=[]);const near=list.find(k=>Math.abs(k.time-t)<.5/project.fps);if(near){near.time=t;near.value=value;return near;}
 const k={id:uid('k'),time:t,value,ease:['text','select','boolean'].includes(SCHEMA[prop].type)?'hold':'ease',curve:[.42,0,.58,1]};list.push(k);list.sort((a,b)=>a.time-b.time);return k;}
function addKey(prop=activeProp){if(rendering)return;activeProp=prop;const v=E.valueAt(project,selected,prop,time);if(v===undefined){toast('此属性不适用于当前选择');return;}remember();const k=upsert(selected,prop,time,v);selectedKey={track:trackKey(),id:k.id};commit();toast(SCHEMA[prop].label+'：已在 '+time.toFixed(2)+'s 添加关键帧');}
function setProp(prop,raw){if(rendering)return;try{const v=validateValue(prop,raw);remember();activeProp=prop;const key=trackKey();if(autoKey||project.tracks[key]?.length){if(!project.tracks[key]?.length&&time>0)upsert(selected,prop,0,E.valueAt(project,selected,prop,0));const k=upsert(selected,prop,time,v);selectedKey={track:key,id:k.id};}else{scopeObject()[prop]=v;selectedKey=null;}commit({rebuild:prop==='points'||prop.startsWith('swap')});}catch(e){toast(e.message);syncInputs();}}
function removeKey(){const key=findKey();if(!key){toast('请先选择一个关键帧');return;}mutate(()=>{const list=project.tracks[selectedKey.track];list.splice(list.findIndex(k=>k.id===key.id),1);if(!list.length)delete project.tracks[selectedKey.track];selectedKey=null;});}
function undo(redo=false){if(rendering)return;const src=redo?future:history,dst=redo?history:future;if(!src.length)return;dst.push(JSON.stringify(project));project=JSON.parse(src.pop());if(selected!=='scene'&&!project.rankers.some(r=>r.id===selected))selected=project.rankers[0].id;selectedKey=null;time=Math.min(time,project.duration);resizePreview();commit();toast(redo?'已重做':'已撤销');}
function renderLayers(){const host=$('rankerList');host.replaceChildren();project.rankers.forEach((r,i)=>{const b=document.createElement('button');b.className='ranker'+(selected===r.id?' selected':'');b.setAttribute('aria-pressed',String(selected===r.id));b.innerHTML='<span class="layerNum">'+String(i+1).padStart(2,'0')+'</span><span class="layerIcon">'+(r.highlight?'★':'R')+'</span><span class="layerName"></span><span class="layerPt"></span>';b.querySelector('.layerName').textContent=r.name;b.querySelector('.layerPt').textContent=Math.round(E.point(project,r.id,time))+'pt';b.onclick=()=>select(r.id);host.append(b);});$('rankerCount').textContent=String(project.rankers.length).padStart(2,'0');$('selectScene').classList.toggle('selected',selected==='scene');$('duplicateBtn').disabled=selected==='scene';$('deleteRanker').disabled=selected==='scene'||project.rankers.length===1;}
function propControl(prop){
 const s=SCHEMA[prop],v=E.valueAt(project,selected,prop,time),el=document.createElement('div');el.className='prop'+(activeProp===prop?' focused':'');el.dataset.prop=prop;
 const label=document.createElement('label');label.htmlFor='prop-'+prop;const name=document.createElement('span');name.textContent=s.label;label.append(name);if(s.unit){const unit=document.createElement('span');unit.className='propUnit';unit.textContent=s.unit;label.append(unit);}
 const k=document.createElement('button');k.className='propKey'+(project.tracks[selected+'.'+prop]?.length?' hasKey':'');k.textContent='◇';k.title='为'+s.label+'添加关键帧 (K)';k.setAttribute('aria-label',k.title);k.onclick=e=>{e.preventDefault();addKey(prop);};label.append(k);el.append(label);
 let input;
 if(s.type==='select'){input=document.createElement('select');const choices=s.options.map(o=>Array.isArray(o)?o:[o,o]);if(prop==='font'){customFonts.forEach(f=>choices.push([f,f]));if(!choices.some(c=>c[0]===v))choices.push([v,v]);}for(const[value,label]of choices){const opt=new Option(label,value);input.append(opt);}}
 else{input=document.createElement('input');input.type=s.type==='boolean'?'checkbox':s.type==='color'?'color':s.type;if(s.type==='number'){input.min=s.min;input.max=s.max;input.step=s.step;}if(s.type==='text')input.maxLength=300;}
 input.id='prop-'+prop;input.dataset.control=prop;if(s.type==='boolean')input.checked=v;else input.value=displayValue(v,s);input.onfocus=()=>selectProp(prop);input.onchange=()=>setProp(prop,s.type==='boolean'?input.checked:input.value);
 if(s.type==='color'){const wrap=document.createElement('div');wrap.className='propColor';const hex=document.createElement('input');hex.type='text';hex.value=v;hex.maxLength=7;hex.setAttribute('aria-label',s.label+'十六进制');hex.dataset.hex=prop;hex.onfocus=()=>selectProp(prop);hex.onchange=()=>setProp(prop,hex.value);wrap.append(input,hex);el.append(wrap);}else el.append(input);
 if(selected!=='scene'&&!Object.hasOwn(scopeObject(),prop)){const hint=document.createElement('div');hint.className='propHint';hint.textContent='继承全局设置';el.append(hint);}
 return el;
}
function displayValue(v,s){return s.type==='number'?Number(Number(v).toFixed(s.step<1?3:2)):v??'';}
function renderProps(){
 $('inspectorTitle').textContent=selected==='scene'?'全局属性':scopeObject().name;$('selectionTag').textContent=selected==='scene'?'COMP':'R'+String(project.rankers.findIndex(r=>r.id===selected)+1).padStart(2,'0');
 const host=$('properties');host.replaceChildren();for(const[title,props]of GROUPS[selected==='scene'?'scene':'row'][tab]){const section=document.createElement('section');section.className='propSection';const h=document.createElement('h3');h.textContent=title;section.append(h);props.forEach(prop=>section.append(propControl(prop)));host.append(section);}
 const actions=document.createElement('div');actions.className='propActions';if(tab==='content'||tab==='style'){const f=document.createElement('button');f.textContent='＋ 载入字体';f.onclick=()=>$('fontFile').click();actions.append(f);}
 if(selected!=='scene'&&tab==='style'){const b=document.createElement('button');b.textContent='样式跟随全局';b.onclick=()=>mutate(()=>{for(const prop of ['width','height','radius','stroke','innerStroke','inset','shadow','fill','strokeColor','badgeColor','badgeText','textColor','nameColor','ptColor','texture','font','nameSize','ptSize','rankSize']){delete scopeObject()[prop];delete project.tracks[selected+'.'+prop];}});actions.append(b);}
 if(selected==='scene'&&tab==='content'){const d=document.createElement('label');d.className='prop';d.textContent='合成时长（秒，最大 120）';const inp=document.createElement('input');inp.type='number';inp.value=project.duration;inp.min=.1;inp.max=120;inp.step=.1;inp.onchange=()=>{const dur=Number(inp.value);const latest=Math.max(0,...Object.values(project.tracks).flat().map(k=>k.time));if(!Number.isFinite(dur)||dur<latest||dur<.1||dur>120){toast('时长须在 '+Math.max(.1,latest).toFixed(2)+'–120 秒之间，不能截断现有关键帧');inp.value=project.duration;return;}mutate(()=>{project.duration=dur;time=Math.min(time,dur);});};d.append(inp);host.append(d);}
 host.append(actions);
}
function trackProps(){const props=new Set(selected==='scene'?['rotation','skew','scale']:['points','x','y']);for(const key of Object.keys(project.tracks))if(key.startsWith(selected+'.'))props.add(key.slice(selected.length+1));props.add(activeProp);return [...props].filter(p=>SCHEMA[p]);}
function renderTimeline(){
 const count=project.duration<=15?6:8;$('ruler').replaceChildren();for(let i=0;i<=count;i++){const span=document.createElement('span');span.style.left=i/count*100+'%';span.textContent=Number((i/count*project.duration).toFixed(1))+'s';$('ruler').append(span);}
 const labels=$('trackLabels'),rows=$('trackRows');labels.replaceChildren();rows.replaceChildren();
 for(const prop of trackProps()){
 const key=selected+'.'+prop,keys=project.tracks[key]||[],label=document.createElement('div');label.className='trackLabel'+(prop===activeProp?' selected':'');label.textContent=(keys.length?'◇ ':'')+SCHEMA[prop].label;const val=document.createElement('small');val.dataset.trackval=prop;label.append(val);label.onclick=()=>selectProp(prop);labels.append(label);
 const row=document.createElement('div');row.className='trackRow'+(prop===activeProp?' selected':'');row.dataset.prop=prop;
 if(keys.length>1){const seg=document.createElement('div');seg.className='trackSegment';seg.style.left=keys[0].time/project.duration*100+'%';seg.style.width=(keys[keys.length-1].time-keys[0].time)/project.duration*100+'%';row.append(seg);}
 keys.forEach(k=>{const d=document.createElement('button');d.className='diamond'+(selectedKey?.id===k.id?' selected':'');d.style.left=k.time/project.duration*100+'%';d.setAttribute('aria-label',SCHEMA[prop].label+' '+k.time.toFixed(2)+'秒关键帧');d.title=k.time.toFixed(2)+'s · '+k.value;d.onpointerdown=e=>startKeyDrag(e,k,key,d);d.onclick=e=>e.stopPropagation();d.ondblclick=e=>{e.stopPropagation();selectedKey={track:key,id:k.id};activeProp=prop;openCurve();};d.onkeydown=e=>{if(e.key==='Enter'){selectedKey={track:key,id:k.id};activeProp=prop;openCurve();}};row.append(d);});
 row.onpointerdown=e=>{if(e.target.closest('.diamond'))return;activeProp=prop;selectedKey=null;startSeek(e);};rows.append(row);
 }
 syncTime();
}
function startSeek(e){if(rendering)return;const bounds=$('trackArea').getBoundingClientRect();const move=ev=>seek((ev.clientX-bounds.left)/bounds.width*project.duration);move(e);const target=e.currentTarget;target.setPointerCapture(e.pointerId);target.addEventListener('pointermove',move);const end=()=>{target.removeEventListener('pointermove',move);target.removeEventListener('pointerup',end);target.removeEventListener('pointercancel',end);renderTimeline();renderKeyPanel();};target.addEventListener('pointerup',end);target.addEventListener('pointercancel',end);}
function startKeyDrag(e,key,track,element){if(rendering)return;e.stopPropagation();remember();selectedKey={track,id:key.id};activeProp=track.split('.')[1];seek(key.time);document.querySelectorAll('.diamond').forEach(d=>d.classList.remove('selected'));element.classList.add('selected');const bounds=$('trackArea').getBoundingClientRect();let moved=false;const startX=e.clientX;
 element.setPointerCapture(e.pointerId);const move=ev=>{if(Math.abs(ev.clientX-startX)<2&&!moved)return;moved=true;const t=E.clamp(Math.round((ev.clientX-bounds.left)/bounds.width*project.duration*project.fps)/project.fps,0,project.duration);if((project.tracks[track]||[]).some(k=>k.id!==key.id&&Math.abs(k.time-t)<.5/project.fps))return;key.time=t;element.style.left=t/project.duration*100+'%';seek(t);};
 const end=()=>{element.removeEventListener('pointermove',move);element.removeEventListener('pointerup',end);element.removeEventListener('pointercancel',end);if(moved){project.tracks[track].sort((a,b)=>a.time-b.time);commit();}else{history.pop();renderKeyPanel();}};element.addEventListener('pointermove',move);element.addEventListener('pointerup',end);element.addEventListener('pointercancel',end);renderKeyPanel();}
function renderKeyPanel(){const k=findKey();$('activeProperty').textContent=SCHEMA[activeProp].label+' / '+activeProp;$('keyPanel').querySelector('p').textContent=k?'已选择 '+k.time.toFixed(2)+'s 关键帧 · 双击菱形编辑曲线':'点击属性右侧 ◇ 打关键帧';}
function syncTime(){const frame=Math.min(Math.floor(time*project.fps+1e-5),Math.round(project.duration*project.fps));const secs=Math.floor(frame/project.fps);$('timecode').textContent=[Math.floor(secs/3600),Math.floor(secs/60)%60,secs%60,frame%project.fps].map(v=>String(v).padStart(2,'0')).join(':');$('playhead').style.left=time/project.duration*100+'%';document.querySelectorAll('[data-trackval]').forEach(el=>{const v=E.valueAt(project,selected,el.dataset.trackval,time);el.textContent=typeof v==='number'?Number(v.toFixed(2)):'';});}
function syncInputs(){document.querySelectorAll('[data-control]').forEach(el=>{if(document.activeElement===el)return;const prop=el.dataset.control,s=SCHEMA[prop],v=E.valueAt(project,selected,prop,time);if(s.type==='boolean')el.checked=v;else el.value=displayValue(v,s);});document.querySelectorAll('[data-hex]').forEach(el=>{if(document.activeElement!==el)el.value=E.valueAt(project,selected,el.dataset.hex,time);});}
function renderUI(){renderLayers();renderProps();renderTimeline();renderKeyPanel();$('projectName').value=project.name;$('durationLabel').textContent=project.duration.toFixed(2)+' s';$('canvasInfo').textContent=project.width+' × '+project.height+' · '+project.fps+' fps';$('previewScale').value=project.preview;$('undoBtn').disabled=!history.length;$('redoBtn').disabled=!future.length;}
function fitCanvas(){const stage=$('stage'),wrap=$('canvasWrap');const style=getComputedStyle(stage);const width=stage.clientWidth-parseFloat(style.paddingLeft)-parseFloat(style.paddingRight),height=stage.clientHeight-parseFloat(style.paddingTop)-parseFloat(style.paddingBottom);const ratio=project.width/project.height;wrap.style.width=Math.min(width,height*ratio)+'px';wrap.style.aspectRatio=String(ratio);wrap.style.height='auto';}
function resizePreview(){if(!sketch)return;const w=project.preview,h=Math.round(w*project.height/project.width);sketch.resizeCanvas(w,h);fitCanvas();}
function togglePlay(){if(rendering)return;if(time>=project.duration)time=0;playing=!playing;lastTick=performance.now();$('playBtn').textContent=playing?'Ⅱ':'▶';$('playBtn').setAttribute('aria-label',playing?'暂停':'播放');}
function download(blob,name){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
function safeName(){return project.name.replace(/[\\/:*?"<>|]/g,'_').slice(0,70)||'rank-motion';}
function saveProject(){download(new Blob([JSON.stringify(project,null,2)],{type:'application/json'}),safeName()+'.rank.json');toast('工程 JSON 已下载'+(persistFailed?'，请妥善保存':''));}
function openCurve(){let k=findKey();if(!k){const keys=project.tracks[trackKey()]||[];if(!keys.length){toast('请先为当前属性添加关键帧');return;}k=keys.reduce((a,b)=>Math.abs(a.time-time)<Math.abs(b.time-time)?a:b);selectedKey={track:trackKey(),id:k.id};}
 curveDraft=clone(k);$('curveContext').textContent=(selected==='scene'?'排名表':scopeObject().name)+' · '+SCHEMA[activeProp].label;$('keyTime').value=k.time;$('keyTime').max=project.duration;
 const type=SCHEMA[activeProp].type,discrete=['text','select','boolean'].includes(type);$('keyValue').type=type==='number'?'number':'text';$('keyValue').step=SCHEMA[activeProp].step||'any';$('keyValue').value=k.value;$('easePreset').value=discrete?'hold':k.ease;$('easePreset').disabled=discrete;
 if(discrete)curveDraft.ease='hold';renderCurve();$('curveDialog').showModal();}
function renderCurve(){const c=curveDraft.curve,[x1,y1,x2,y2]=c;const pos=(x,y)=>[40+x*275,230-y*200],a=pos(x1,y1),b=pos(x2,y2);
 $('curvePath').setAttribute('d',curveDraft.ease==='hold'?'M40 230H315V30':`M40 230 C${a[0]} ${a[1]},${b[0]} ${b[1]},315 30`);
 for(const[i,p,origin]of [[1,a,[40,230]],[2,b,[315,30]]]){const h=$('handle'+i),l=$('handleLine'+i);h.setAttribute('cx',p[0]);h.setAttribute('cy',p[1]);h.style.display=curveDraft.ease==='hold'?'none':'';l.setAttribute('x1',origin[0]);l.setAttribute('y1',origin[1]);l.setAttribute('x2',p[0]);l.setAttribute('y2',p[1]);h.setAttribute('aria-valuetext',`x ${c[(i-1)*2].toFixed(2)}, y ${c[(i-1)*2+1].toFixed(2)}`);}
 const host=$('curveNumbers');host.replaceChildren();['x₁','y₁','x₂','y₂'].forEach((label,i)=>{const l=document.createElement('label');l.textContent=label;const input=document.createElement('input');input.type='number';input.step=.01;input.min=i%2?-4:0;input.max=i%2?4:1;input.value=Number(c[i].toFixed(3));input.disabled=curveDraft.ease==='hold';input.onchange=()=>{curveDraft.curve[i]=E.clamp(Number(input.value)||0,i%2?-4:0,i%2?4:1);curveDraft.ease='custom';$('easePreset').value='custom';renderCurve();};l.append(input);host.append(l);});}
function curveDrag(e,index){e.preventDefault();const el=e.currentTarget;el.setPointerCapture(e.pointerId);const move=ev=>{const point=new DOMPoint(ev.clientX,ev.clientY).matrixTransform($('curveGraph').getScreenCTM().inverse());const x=point.x,y=point.y;curveDraft.curve[index*2]=E.clamp((x-40)/275,0,1);curveDraft.curve[index*2+1]=E.clamp((230-y)/200,-4,4);curveDraft.ease='custom';$('easePreset').value='custom';renderCurve();};const end=()=>{el.removeEventListener('pointermove',move);el.removeEventListener('pointerup',end);};el.addEventListener('pointermove',move);el.addEventListener('pointerup',end);}
function openBoost(){if(selected==='scene')select(project.rankers[project.rankers.length-1].id);playing=false;$('playBtn').textContent='▶';$('boostWho').textContent=scopeObject().name+' · '+time.toFixed(2)+'s · 当前 '+E.point(project,selected,time).toFixed(1)+'pt';$('boostTarget').value=Math.ceil(Math.max(...project.rankers.map(r=>E.point(project,r.id,time)))+2);$('boostDuration').value=Math.min(3,Math.max(.1,project.duration-time));$('boostDialog').showModal();}
function addBoost(target,duration){target=validateValue('points',target);if(!Number.isFinite(duration)||duration<.1||duration>120||time+duration>project.duration+.00001)throw Error('积分动画结束时间超出合成时长，请延长合成或缩短增长动画');const current=E.point(project,selected,time);remember();const key=selected+'.points';project.tracks[key]=(project.tracks[key]||[]).filter(k=>k.time<time-.0001||k.time>time+duration+.0001);const a=upsert(selected,'points',time,current);upsert(selected,'points',time+duration,target);activeProp='points';selectedKey={track:key,id:a.id};commit();}
