$('applyCurveBtn').onclick=()=>{try{const key=findKey();if(!key)throw Error('此关键帧已不存在');const t=Number($('keyTime').value);if(!Number.isFinite(t)||t<0||t>project.duration)throw Error('关键帧时间超出合成范围');if(project.tracks[selectedKey.track].some(k=>k.id!==key.id&&Math.abs(k.time-t)<.00001))throw Error('该时间已有关键帧');const type=SCHEMA[activeProp].type,raw=$('keyValue').value;let value=raw;if(type==='boolean'){if(!['true','false'].includes(raw))throw Error('开关值请输入 true 或 false');value=raw==='true';}value=validateValue(activeProp,value);remember();Object.assign(key,curveDraft,{time:t,value});project.tracks[selectedKey.track].sort((a,b)=>a.time-b.time);seek(t);commit();$('curveDialog').close();}catch(e){toast(e.message);}};
