window.addEventListener('keydown',e=>{if(e.key==='Escape'&&rendering){cancelled=true;return;}if(e.key.toLowerCase()==='k'&&e.target.matches('input[type=number]')&&!document.querySelector('dialog[open]')){e.preventDefault();e.target.blur();addKey();return;}if(e.target.matches('input,select,textarea')||e.target.isContentEditable)return;if(document.querySelector('dialog[open]'))return;const cmd=e.metaKey||e.ctrlKey;if(cmd&&e.key.toLowerCase()==='s'){e.preventDefault();saveProject();return;}if(cmd&&e.key.toLowerCase()==='z'){e.preventDefault();undo(e.shiftKey);return;}if(rendering)return;if(e.code==='Space'){e.preventDefault();togglePlay();}else if(e.key.toLowerCase()==='k'){e.preventDefault();addKey();}else if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();seek(time+(e.key==='ArrowRight'?1:-1)*(e.shiftKey?10:1)/project.fps);}else if(e.key==='Delete'||e.key==='Backspace'){if(findKey()){e.preventDefault();removeKey();}}else if(e.key==='?')$('helpDialog').showModal();});
window.addEventListener('beforeunload',e=>{if(rendering||persistFailed){e.preventDefault();e.returnValue='';}});
// WebMCP: uses the same state, validation and score action as the visible editor.
function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;const life=new AbortController();const defs=[
 {name:'read_ranking_project',title:'读取排名动画工程',description:'读取当前合成、播放时间与选手积分，不修改工程。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({name:project.name,time,duration:project.duration,width:project.width,height:project.height,fps:project.fps,rankers:project.rankers.map(r=>({id:r.id,name:r.name,points:E.point(project,r.id,time)}))})},
 {name:'create_score_animation',title:'创建积分与换位动画',description:'为指定选手从当前播放时间创建积分动画，写入两个关键帧并自动重算排名。',inputSchema:{type:'object',properties:{rankerId:{type:'string'},target:{type:'number',minimum:0,maximum:9999999},duration:{type:'number',minimum:.1,maximum:120}},required:['rankerId','target','duration'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(rendering)throw Error('正在导出');if(!input||!project.rankers.some(r=>r.id===input.rankerId)||!Number.isFinite(input.target)||!Number.isFinite(input.duration)||input.target<0||input.target>9999999||input.duration<.1||time+input.duration>project.duration)throw Error('无效选手或动画参数');selected=input.rankerId;addBoost(input.target,input.duration);return {rankerId:selected,start:time,end:time+input.duration,target:input.target};}}
 ];for(const tool of defs){try{Promise.resolve(context.registerTool(tool,{signal:life.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>life.abort(),{once:true});}
events=E.compileRanking(project);renderUI();
new p5(p=>{sketch=p;p.setup=()=>{p.pixelDensity(1);p5canvas=p.createCanvas(project.preview,Math.round(project.preview*project.height/project.width));p5canvas.parent('canvasHost');p.frameRate(60);p5canvas.elt.setAttribute('aria-label','排名动画画布');resizeObserver=new ResizeObserver(fitCanvas);resizeObserver.observe($('stage'));lastTick=performance.now();fitCanvas();};p.draw=()=>{const now=performance.now();if(playing&&!rendering){time+=(now-lastTick)/1000;if(time>project.duration){if(loop)time%=project.duration;else{time=project.duration;playing=false;$('playBtn').textContent='▶';}}}lastTick=now;if(!rendering)E.render(p.drawingContext,project,time,p.width,p.height,events);if(now-lastUI>80){syncTime();if(playing)syncInputs();lastUI=now;}};});
registerTools();
